mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, T4.ASSET_TYPE1 assetType1, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T2.PORTFOLIO_NAME portfolioName, T1.PRICE*100 price, T4.TERM_TYPE termType, T4.BUSI_PS ps,
T1.ENTRUST_NUM*100 entrustAmt, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, T1.PRICE_MODEL priceModel, NVL(T5.FINISH_AMT,0)*100 finishAmt, round(NVL(T5.FINISH_AMT,0)/ NVL(T1.ENTRUST_NUM, T1.ENTRUST_AMT),4)*100 transactioncom, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN ETR_ENTRUST_ADD T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(NVL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND T4.ASSET_TYPE1 = #{assetType1}
AND T1.CCY = #{ccy}
AND T1.PS=#{ps}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.PRICE_MODEL = #{priceModel}
AND T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N})
order by T1.ENTRUST_ID DESC

SELECT T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
AND T1.PORTFOLIO_TYPE != '02'
AND T1.PORTFOLIO_ID = #{initValue}
AND (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))

select TYPE_6 assetType1 from FIN_PRODUCT_TYPE
where 
FINPROD_ID = #{finprodId}

select T7.PORTFOLIO_ID,T7.SEC_ACCT_ID,SUM(T7.AMT) PRIN_AMT from( select T1.PORTFOLIO_ID,T1.SEC_ACCT_ID,T2.FINPROD_ID,SUM(DECODE(T1.PS,#{pin},T2.AMT,#{pout},T2.AMT*-1)*NVL(T6.SCALE,0)) AMT from TRD_STASEC_FLOW T1 INNER JOIN TRD_STASEC_FLOW_DETAIL T2 ON T1.SEQNO = T2.SEQNO left join (select T3.FINPROD_ID,T3.SCALE from FIN_STDSEC_CONVERSE_RADIO T3 INNER JOIN (select T4.FINPROD_ID,MAX(T4.VDATE) VDATE from FIN_STDSEC_CONVERSE_RADIO T4
T4.VDATE <= #{sysDate}
group by T4.FINPROD_ID) T5 ON T3.FINPROD_ID = T5.FINPROD_ID
T3.VDATE = T5.VDATE
) T6 ON T6.FINPROD_ID = T2.FINPROD_ID
T1.PORTFOLIO_ID = #{portfolioId} AND T1.SEC_ACCT_ID = #{manageId}
group by T1.PORTFOLIO_ID,T1.SEC_ACCT_ID,T2.FINPROD_ID ) T7 group by T7.PORTFOLIO_ID,T7.SEC_ACCT_ID

SELECT A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.ACCT_NO = #{initValue}
AND TRADE_PLACE = #{tradeMarket}
